-- An editable starter document, deliberately without invented legal clauses.
create function public.initial_contract_template() returns trigger language plpgsql security definer set search_path='' as $$begin
 insert into public.tenant_configuration(tenant_id,category,key,value) values(new.id,'document','contract',jsonb_build_object('title','Contrato de crédito','body','{microcredito} concede a {nome} o crédito {contrato}.\nMontante pedido: {montante}. Desembolso: {desembolso}.\nTotal a pagar: {total}. Juros: {juros}. Comissões e impostos: {encargos}.\nTaxa efectiva anual: {taxa_anual}. O plano de prestações faz parte deste contrato.\nFinalidade: {finalidade}.\nAssinatura do cliente: ____________________\nAssinatura do microcrédito: ____________________')) on conflict do nothing;
 return new;end;$$;
revoke all on function public.initial_contract_template() from public,anon,authenticated;
create trigger initial_contract_template after insert on public.tenants for each row execute function public.initial_contract_template();
insert into public.tenant_configuration(tenant_id,category,key,value) select id,'document','contract',jsonb_build_object('title','Contrato de crédito','body','{microcredito} concede a {nome} o crédito {contrato}.\nMontante pedido: {montante}. Desembolso: {desembolso}.\nTotal a pagar: {total}. Juros: {juros}. Comissões e impostos: {encargos}.\nTaxa efectiva anual: {taxa_anual}. O plano de prestações faz parte deste contrato.\nFinalidade: {finalidade}.\nAssinatura do cliente: ____________________\nAssinatura do microcrédito: ____________________') from public.tenants on conflict do nothing;
